package dev.veltraph.client.navigation;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Executable pure counterexamples; no native client or fixture permission is involved. */
class LegacyTravelPublicationIdentityTest {
    final Object root=new Object(),parent=new Object(),player=new Object(),world=new Object(),connection=new Object(),config=new Object(),service=new Object(),leg=new Object();
    LegacyTravelPublicationIdentity.State state(long generation,long epoch){return new LegacyTravelPublicationIdentity.State(root,parent,parent,parent,player,world,connection,config,3,7,service,generation,epoch,20,leg,true,true,true);}
    LegacyTravelPublicationIdentity.State serial(LegacyTravelPublicationIdentity.State s,long serial){return new LegacyTravelPublicationIdentity.State(s.root(),s.parent(),s.inputOwner(),s.cameraAuthority(),s.player(),s.world(),s.connection(),s.config(),s.revision(),s.journey(),s.service(),s.requestGeneration(),s.epoch(),serial,s.activeLeg(),s.registered(),s.enabled(),s.usable());}
    LegacyTravelPublicationIdentity.State journey(LegacyTravelPublicationIdentity.State s,long journey){return new LegacyTravelPublicationIdentity.State(s.root(),s.parent(),s.inputOwner(),s.cameraAuthority(),s.player(),s.world(),s.connection(),s.config(),s.revision(),journey,s.service(),s.requestGeneration(),s.epoch(),s.publicationSerial(),s.activeLeg(),s.registered(),s.enabled(),s.usable());}
    LegacyTravelPublicationIdentity.State disabled(LegacyTravelPublicationIdentity.State s){return new LegacyTravelPublicationIdentity.State(s.root(),s.parent(),s.inputOwner(),s.cameraAuthority(),s.player(),s.world(),s.connection(),s.config(),s.revision(),s.journey(),s.service(),s.requestGeneration(),s.epoch(),s.publicationSerial(),s.activeLeg(),s.registered(),false,false);}
    LegacyTravelPublicationIdentity.State policy(LegacyTravelPublicationIdentity.State s,long revision,boolean usable){return new LegacyTravelPublicationIdentity.State(s.root(),s.parent(),s.inputOwner(),s.cameraAuthority(),s.player(),s.world(),s.connection(),s.config(),revision,s.journey(),s.service(),s.requestGeneration(),s.epoch(),s.publicationSerial(),s.activeLeg(),s.registered(),s.enabled(),usable);}
    LegacyTravelPublicationIdentity.State active(LegacyTravelPublicationIdentity.State s,Object active){return new LegacyTravelPublicationIdentity.State(s.root(),s.parent(),s.inputOwner(),s.cameraAuthority(),s.player(),s.world(),s.connection(),s.config(),s.revision(),s.journey(),s.service(),s.requestGeneration(),s.epoch(),s.publicationSerial(),active,s.registered(),s.enabled(),s.usable());}
    LegacyTravelPublicationIdentity.Publication pub(long beforeEpoch,long afterEpoch,long beforeSerial){return new LegacyTravelPublicationIdentity.Publication(serial(state(4,beforeEpoch),beforeSerial),serial(state(4,afterEpoch),beforeSerial+1),beforeSerial+1);}
    LegacyTravelPublicationIdentity.Lease lease(){return LegacyTravelPublicationIdentity.Lease.capture(state(4,9));}
    LegacyTravelPublicationIdentity.State change(LegacyTravelPublicationIdentity.State s,String field){
        Object foreign=new Object();return new LegacyTravelPublicationIdentity.State(field.equals("root")?foreign:s.root(),field.equals("parent")?foreign:s.parent(),field.equals("input")?foreign:s.inputOwner(),field.equals("camera")?foreign:s.cameraAuthority(),field.equals("player")?foreign:s.player(),field.equals("world")?foreign:s.world(),field.equals("connection")?foreign:s.connection(),field.equals("config")?foreign:s.config(),s.revision()+(field.equals("revision")?1:0),s.journey()+(field.equals("journey")?1:0),field.equals("service")?foreign:s.service(),s.requestGeneration()+(field.equals("generation")?1:0),s.epoch()+(field.equals("epoch")?1:0),s.publicationSerial()+(field.equals("serial")?1:0),field.equals("leg")?foreign:s.activeLeg(),!field.equals("registration"),!field.equals("disabled"),!field.equals("scene"));
    }
    LegacyTravelRetirement.RetirementOutcome refuseForeignRetirement(LegacyTravelPublicationIdentity.Lease lease,LegacyTravelPublicationIdentity.State live){return LegacyTravelRetirement.retire(new LegacyTravelRetirement.Effects(){
        public boolean keysPublished(){return lease.keysPublished();}public boolean cameraPublishedOrQueued(){return lease.cameraPublishedOrQueued();}
        public boolean activeLegMatches(){return live.activeLeg()==leg;}public boolean cleanupFence(){return lease.cleanupCurrent(live);}
        public boolean release(LegacyTravelRetirement.Key key){fail("Foreign/newer key release attempted");return false;}
        public boolean cancelCamera(){fail("Foreign/newer camera cancellation attempted");return false;}
        public LegacyTravelRetirement.Removal retireLogical(){lease.closed();return live.activeLeg()==leg?LegacyTravelRetirement.Removal.REMOVED_OWN:LegacyTravelRetirement.Removal.FOREIGN_PRESERVED;}
    });}
    @Test void capturedEpochAloneGrantsNoCameraOrKeysCleanup(){var l=lease();assertTrue(l.current(state(4,9)));assertFalse(l.mayCancelCamera(state(4,9)));assertFalse(l.mayReleaseKeys(state(4,9)));}
    @Test void firstActualPublicationRecordsRealControlTicketAndOwnEpoch(){var l=lease();assertTrue(l.published(pub(9,10,20)));assertEquals(21,l.ticket());assertEquals(10,l.epoch());assertTrue(l.mayCancelCamera(serial(state(4,10),21)));assertFalse(l.current(state(4,9)));}
    @Test void eachActualPlanCanKeepOrAdvanceEpoch(){var l=lease();assertTrue(l.published(pub(9,9,20)));assertTrue(l.published(pub(9,10,21)));assertTrue(l.published(pub(10,10,22)));assertEquals(23,l.ticket());}
    @Test void zeroOrNegativeTicketsAndRawLateEpochCannotBeAdopted(){for(long ticket:new long[]{-1,0})assertFalse(lease().published(new LegacyTravelPublicationIdentity.Publication(state(4,9),state(4,10),ticket)));var l=lease();assertFalse(l.current(state(4,10)));assertEquals(9,l.epoch());assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(state(4,10),state(4,10),8)));assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(state(4,9),state(4,11),8)));}
    @Test void foreignBeforePublicationRefusesEvenIfAfterReturnsToParent(){for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","revision","journey","service","generation","epoch","serial","leg","registration","disabled","scene"})assertFalse(lease().published(new LegacyTravelPublicationIdentity.Publication(change(state(4,9),field),serial(state(4,10),21),21)),field);}
    @Test void contextLostDuringPublicationCannotRefreshCameraIdentity(){for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","revision","journey","service","generation","serial","leg","registration","disabled","scene"}){var l=lease();assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(state(4,9),change(serial(state(4,10),21),field),21)),field);assertEquals(9,l.epoch());assertEquals(0,l.ticket());}}
    @Test void sameParentNewRequestAtSameEpochPreventsOldKeysAndCameraCleanup(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));assertFalse(l.current(serial(state(5,9),21)));assertFalse(l.mayReleaseKeys(serial(state(5,9),21)));assertFalse(l.mayCancelCamera(serial(state(5,9),21)));}
    @Test void newerSameParentLegAndForeignRootOrPwcRejectCleanup(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","journey","service","serial","leg","registration"}){assertFalse(l.mayReleaseKeys(change(serial(state(4,9),21),field)),field);assertFalse(l.mayCancelCamera(change(serial(state(4,9),21),field)),field);}}
    @Test void contextLostDuringGeometryMeansEveryLaterNormalKeyIsRefused(){var l=lease();assertTrue(l.current(state(4,9)));var afterGeometry=change(state(4,9),"scene");assertFalse(l.current(afterGeometry));assertFalse(l.inputPublished(afterGeometry,afterGeometry));assertFalse(l.mayReleaseKeys(afterGeometry));}
    @Test void actualKeyBeforeAndAfterMustRemainSameLeg(){var l=lease();assertFalse(l.inputPublished(state(4,9),change(state(4,9),"generation")));assertFalse(l.mayReleaseKeys(state(4,9)));assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.mayReleaseKeys(change(state(4,9),"scene")));}
    @Test void queuedSourceGetsIndependentGenerationAndNoCopiedCameraTicket(){var l=lease();assertTrue(l.queued(state(4,9),state(5,9)));assertEquals(5,l.generation());assertEquals(0,l.ticket());assertFalse(l.mayCancelCamera(state(5,9)));assertFalse(l.current(state(4,9)));assertFalse(l.refreshedSource(state(5,9),serial(state(6,10),21),5,10,21));assertEquals(9,l.epoch());}
    @Test void foreignQueuedRequestCannotBecomeOwnViaCapturedCurrentStamp(){var l=lease();assertFalse(l.queued(state(5,9),state(6,9)));assertFalse(l.refreshedSource(state(4,9),serial(state(5,10),21),5,10,21));assertFalse(l.mayCancelCamera(state(4,9)));assertFalse(l.refreshedSource(state(4,9),serial(state(4,10),21),4,10,21));assertFalse(l.cancelled(state(4,9),state(4,10),false));}
    @Test void onlySameQueuedSourceCertifiedTransitionRefreshesItsEpoch(){var l=lease();assertTrue(l.queued(state(4,9),state(5,9)));assertTrue(l.refreshedSource(state(5,9),serial(state(5,10),21),5,10,21));assertTrue(l.current(serial(state(5,10),21)));assertFalse(l.refreshedSource(serial(state(5,10),21),change(serial(state(5,11),22),"camera"),5,11,22));assertFalse(l.refreshedSource(serial(state(5,10),21),serial(state(5,12),22),5,12,22));}
    @Test void ownCancelledCameraRefreshesCleanupAndConsumesActualTicket(){var l=lease();assertTrue(l.published(pub(9,9,20)));assertTrue(l.cancelled(serial(state(4,9),21),serial(state(4,10),21),false));assertEquals(10,l.epoch());assertEquals(0,l.ticket());assertTrue(l.cleanupCurrent(serial(state(4,10),21)));assertFalse(l.mayCancelCamera(serial(state(4,10),21)));}
    @Test void ownSourceCancelMustAdvanceIndependentGenerationAndEpoch(){var l=lease();assertTrue(l.queued(state(4,9),state(5,9)));assertFalse(l.cancelled(state(5,9),state(5,10),true));assertTrue(l.cancelled(state(5,9),state(6,10),true));assertEquals(6,l.generation());assertEquals(10,l.epoch());}
    @Test void retirementCannotReleaseOrRebindFromLateReceipts(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));l.closed();assertFalse(l.current(state(4,9)));assertFalse(l.mayReleaseKeys(state(4,9)));assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(state(4,9),state(4,10),12)));assertFalse(l.queued(state(4,9),state(5,9)));}
    @Test void absentDisabledOwnerAllowsOnlyNarrowExactCleanup(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));var absent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,player,world,connection,config,3,7,service,4,9,20,leg,true,false,false);assertFalse(l.current(absent));assertTrue(l.cleanupCurrent(absent));assertTrue(l.mayReleaseKeys(absent));assertFalse(l.cleanupCurrent(change(absent,"camera")));}
    @Test void invalidRootSceneAndRegistrationNeverCapturePermission(){for(String field:new String[]{"input","camera","registration","disabled","scene"})assertNull(LegacyTravelPublicationIdentity.Lease.capture(change(state(4,9),field)),field);}
    @Test void sameParentRawPlanAtSameEpochCannotCancelOrReleasePriorTicket(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));var foreignRaw=serial(state(4,9),22);assertFalse(l.current(foreignRaw));assertFalse(l.mayReleaseKeys(foreignRaw));assertFalse(l.mayCancelCamera(foreignRaw));assertFalse(l.cancelled(foreignRaw,serial(state(4,10),22),false));}
    @Test void returnedTicketMustBeExactNextNativeSerial(){assertFalse(lease().published(new LegacyTravelPublicationIdentity.Publication(state(4,9),serial(state(4,9),21),20)));assertFalse(lease().published(new LegacyTravelPublicationIdentity.Publication(state(4,9),serial(state(4,9),22),22)));}
    @Test void ownPlanNeverCopiesCapturedForeignSourceCancellationPermission(){var l=lease();assertTrue(l.published(pub(9,9,20)));assertTrue(l.mayCancelCamera(serial(state(4,9),21)));assertFalse(l.cancelled(serial(state(4,9),21),serial(state(5,10),21),true));assertTrue(l.cancelled(serial(state(4,9),21),serial(state(4,10),21),false));}
    @Test void admissionSucceedsOnlyForStableVacantSlotAndExactScene(){var before=active(state(4,9),null);Object candidate=new Object();var admitted=LegacyTravelPublicationIdentity.Lease.admit(before,before,candidate,5,5);assertNotNull(admitted);assertTrue(admitted.current(active(before,candidate)));assertFalse(admitted.current(before));assertNull(LegacyTravelPublicationIdentity.Lease.admit(before,change(before,"scene"),candidate,5,5));}
    @Test void failedAdmissionLeavesOldPublishedLeaseCleanupIntact(){var old=lease();assertTrue(old.inputPublished(state(4,9),state(4,9)));assertTrue(old.published(pub(9,9,20)));var live=serial(state(4,9),21);assertNull(LegacyTravelPublicationIdentity.Lease.admit(live,live,new Object(),5,5));assertTrue(old.mayReleaseKeys(live));assertTrue(old.mayCancelCamera(live));}
    @Test void reentrantActiveLegAndAwayBackVersionChangeRefuseAdmission(){var vacant=active(state(4,9),null);assertNull(LegacyTravelPublicationIdentity.Lease.admit(vacant,active(vacant,new Object()),new Object(),5,6));assertNull(LegacyTravelPublicationIdentity.Lease.admit(vacant,vacant,new Object(),5,7));assertNull(LegacyTravelPublicationIdentity.Lease.admit(vacant,serial(vacant,21),new Object(),5,5));}
    @Test void changingRootOrConfigDuringVacantAdmissionCannotCommit(){var vacant=active(state(4,9),null);for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","revision","journey","service","generation","epoch","serial","registration","disabled","scene"})assertNull(LegacyTravelPublicationIdentity.Lease.admit(vacant,change(vacant,field),new Object(),5,5),field);}
    @Test void heldOwnKeysAndCameraRemainCleanableAfterSameStorePolicyAba(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));var revoked=policy(serial(state(4,9),21),5,false);assertFalse(l.current(revoked));assertTrue(l.cleanupCurrent(revoked));assertTrue(l.mayReleaseKeys(revoked));assertTrue(l.mayCancelCamera(revoked));assertFalse(l.inputPublished(revoked,revoked));assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(revoked,serial(revoked,22),22)));assertFalse(l.queued(revoked,policy(serial(state(5,9),21),5,false)));}
    @Test void policyLossNeverPermitsForeignRootPwcStoreOrNewerRequestCleanup(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));var revoked=policy(serial(state(4,9),21),5,false);for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","journey","service","generation","epoch","serial","leg","registration"}){assertFalse(l.mayReleaseKeys(change(revoked,field)),field);assertFalse(l.mayCancelCamera(change(revoked,field)),field);}}
    @Test void ownedCancellationCanFinishAcrossAnotherSameStorePolicyChange(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));var before=policy(serial(state(4,9),21),5,false);var after=policy(serial(state(4,10),21),6,false);assertTrue(l.cancelled(before,after,false));assertFalse(l.current(after));assertTrue(l.mayReleaseKeys(after));assertFalse(l.mayCancelCamera(after));}
    @Test void policyLossWithoutAnyOwnPublicationGrantsNoKeyOrCameraCleanup(){var l=lease();var revoked=policy(state(4,9),5,false);assertTrue(l.cleanupCurrent(revoked));assertFalse(l.mayReleaseKeys(revoked));assertFalse(l.mayCancelCamera(revoked));assertFalse(l.cancelled(revoked,policy(state(4,10),5,false),false));}
    @Test void absentAuthorityCleanupRequiresActuallyDisabledCapturedParent(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));var enabledAbsent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,player,world,connection,config,5,7,service,4,9,20,leg,true,true,false);assertFalse(l.cleanupCurrent(enabledAbsent));var disabledAbsent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,player,world,connection,config,5,7,service,4,9,20,leg,true,false,false);assertTrue(l.mayReleaseKeys(disabledAbsent));assertFalse(l.current(disabledAbsent));}
    @Test void onlyLegQueuedSourceCanCancelAfterSameStorePolicyLoss(){var l=lease();assertTrue(l.queued(state(4,9),state(5,9)));var before=policy(state(5,9),5,false);var after=policy(state(6,10),6,false);assertFalse(l.current(before));assertTrue(l.cancelled(before,after,true));assertTrue(l.cleanupCurrent(after));assertFalse(l.current(after));assertFalse(lease().cancelled(policy(state(4,9),5,false),policy(state(5,10),6,false),true));}
    @Test void retiredParentProofAllowsOnlyExactSameStoreRevokedPolicyCustody(){var l=lease();assertTrue(l.inputPublished(state(4,9),state(4,9)));assertTrue(l.published(pub(9,9,20)));l.closed();var live=active(policy(serial(state(4,9),21),5,false),null);assertTrue(l.ownsRetiredParent(live,true,7,7));assertFalse(l.current(live));assertFalse(l.mayReleaseKeys(live));assertFalse(l.mayCancelCamera(live));}
    @Test void retiredParentProofRejectsForeignNewerAndAbsentAuthorities(){var l=lease();assertTrue(l.published(pub(9,9,20)));l.closed();var live=active(policy(serial(state(4,9),21),5,false),null);for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","journey","service","generation","epoch","serial","leg","registration","disabled"})assertFalse(l.ownsRetiredParent(change(live,field),true,7,7),field);assertFalse(l.ownsRetiredParent(live,false,7,7));assertFalse(l.ownsRetiredParent(live,true,7,9));}
    @Test void retiredParentProofRequiresClosedLegAndExactOwnedCancellationEpoch(){var l=lease();assertTrue(l.published(pub(9,9,20)));var before=serial(state(4,9),21);assertFalse(l.ownsRetiredParent(active(before,null),true,7,7));assertTrue(l.cancelled(before,serial(state(4,10),21),false));l.closed();assertTrue(l.ownsRetiredParent(active(serial(state(4,10),21),null),true,7,7));assertFalse(l.ownsRetiredParent(active(before,null),true,7,7));assertFalse(l.ownsRetiredParent(active(serial(state(4,11),21),null),true,7,7));}
    @Test void actualInputThenCallbackGenerationChangeCannotHideOutstandingNativeKey(){var l=lease();var before=state(4,9);boolean[] held={false};var live=new LegacyTravelPublicationIdentity.State[]{before};assertFalse(l.keysPublished());assertTrue(l.inputAttempted(before));Runnable nativeInput=()->{held[0]=true;live[0]=change(before,"generation");};nativeInput.run();assertFalse(l.inputPublished(before,live[0]));assertTrue(held[0]);assertTrue(l.keysPublished());assertFalse(l.mayReleaseKeys(live[0]));var r=refuseForeignRetirement(l,live[0]);assertTrue(r.keysRequired());assertEquals(LegacyTravelRetirement.Result.NOT_ATTEMPTED,r.keys().get(0));assertTrue(r.hasUnconfirmedOwnedKeys());assertFalse(r.cleanSuccess());assertTrue(held[0]);}
    @Test void actualInputThenSameEpochForeignSerialChangeIsRequiredUnconfirmedCleanup(){var l=lease();var before=state(4,9);assertTrue(l.inputAttempted(before));var foreign=change(before,"serial");assertFalse(l.inputPublished(before,foreign));assertTrue(l.keysPublished());assertEquals(20,l.serial());var r=refuseForeignRetirement(l,foreign);assertTrue(r.keysRequired());assertFalse(r.keys().contains(LegacyTravelRetirement.Result.NOT_OWNED));assertFalse(r.cleanSuccess());}
    @Test void invalidBeforeGuardCannotManufactureAttemptPresence(){var l=lease();var foreign=change(state(4,9),"generation");assertFalse(l.inputAttempted(foreign));assertFalse(l.cameraAttempted(foreign,21));assertFalse(l.sourceAttempted(foreign));assertFalse(l.keysPublished());assertFalse(l.cameraPublishedOrQueued());}
    @Test void nativeInputExceptionBeforePostProofRetainsAttemptAndExactCleanupScope(){var l=lease();var before=state(4,9);boolean[] held={false};assertTrue(l.inputAttempted(before));try{held[0]=true;throw new IllegalStateException("After native mutation");}catch(RuntimeException expected){}assertTrue(held[0]);assertTrue(l.keysPublished());assertTrue(l.mayReleaseKeys(before));assertEquals(4,l.generation());assertEquals(20,l.serial());}
    @Test void actualPositiveCameraPublicationThenForeignCallbackIsNotUnownedOrClean(){var l=lease();var before=state(4,9);long actualTicket=21;assertTrue(l.cameraAttempted(before,actualTicket));var foreign=change(serial(state(4,9),21),"generation");assertFalse(l.published(new LegacyTravelPublicationIdentity.Publication(before,foreign,actualTicket)));assertTrue(l.cameraPublishedOrQueued());assertEquals(0,l.ticket());assertEquals(20,l.serial());assertEquals(9,l.epoch());var r=refuseForeignRetirement(l,foreign);assertTrue(r.cameraRequired());assertEquals(LegacyTravelRetirement.Result.NOT_ATTEMPTED,r.camera());assertFalse(r.cleanSuccess());}
    @Test void actualQueuedSourceAttemptReplacedBeforeCertificationCannotDisappear(){var l=lease();var before=state(4,9);assertTrue(l.sourceAttempted(before));var newer=state(6,9);assertFalse(l.queued(before,newer));assertTrue(l.cameraPublishedOrQueued());assertEquals(4,l.generation());assertFalse(l.mayCancelCamera(newer));var r=refuseForeignRetirement(l,newer);assertTrue(r.cameraRequired());assertEquals(LegacyTravelRetirement.Result.NOT_ATTEMPTED,r.camera());assertFalse(r.cleanSuccess());}
    @Test void sceneLossAfterActualInputStillAllowsOnlyOriginalExactScopeCleanup(){var l=lease();var before=state(4,9);assertTrue(l.inputAttempted(before));var lost=change(before,"scene");assertFalse(l.inputPublished(before,lost));assertFalse(l.current(lost));assertTrue(l.keysPublished());assertTrue(l.mayReleaseKeys(lost));assertFalse(l.mayReleaseKeys(change(lost,"generation")));}
    @Test void certifiedOwnSourceCancellationConsumesItsOutstandingAttempt(){var l=lease();assertTrue(l.sourceAttempted(state(4,9)));assertTrue(l.queued(state(4,9),state(5,9)));assertTrue(l.cameraPublishedOrQueued());assertTrue(l.cancelled(state(5,9),state(6,10),true));assertFalse(l.cameraPublishedOrQueued());}
    @Test void certifiedOwnCameraCancellationConsumesItsOutstandingPositiveAttempt(){var l=lease();assertTrue(l.cameraAttempted(state(4,9),21));assertTrue(l.published(pub(9,9,20)));assertTrue(l.cameraPublishedOrQueued());assertTrue(l.cancelled(serial(state(4,9),21),serial(state(4,10),21),false));assertFalse(l.cameraPublishedOrQueued());}
    @Test void cleanContinuationRequiresOriginalPolicyAndLiveUsableDespiteCleanupOnlyProof(){var l=lease();assertTrue(l.published(pub(9,9,20)));assertTrue(l.cancelled(serial(state(4,9),21),serial(state(4,10),21),false));l.closed();var live=active(serial(state(4,10),21),null);assertTrue(l.ownsRetiredContinuation(live,true,7,7));var changed=policy(live,5,false);assertTrue(l.ownsRetiredParent(changed,true,7,7));assertFalse(l.ownsRetiredContinuation(changed,true,7,7));assertFalse(l.ownsRetiredContinuation(policy(live,5,true),true,7,7));assertFalse(l.ownsRetiredContinuation(policy(live,3,false),true,7,7));}
    @Test void cleanContinuationRejectsRawSameParentPublicationRequestAndInterveningLeg(){var l=lease();l.closed();var live=active(state(4,9),null);assertTrue(l.ownsRetiredContinuation(live,true,7,7));assertFalse(l.ownsRetiredContinuation(change(live,"serial"),true,7,7));assertFalse(l.ownsRetiredContinuation(change(live,"generation"),true,7,7));assertFalse(l.ownsRetiredContinuation(live,true,7,9));assertFalse(l.ownsRetiredContinuation(active(live,new Object()),true,7,7));}
    @Test void retiredCleanupAloneAcceptsTypedDisabledParentWithNoReplacement(){var l=lease();l.closed();var absent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,player,world,connection,config,5,7,service,4,9,20,null,true,false,false);assertTrue(l.ownsRetiredCleanupParent(absent,true,7,7));assertFalse(l.ownsRetiredParent(absent,true,7,7));assertFalse(l.ownsRetiredContinuation(absent,true,7,7));var retainedCamera=new LegacyTravelPublicationIdentity.State(root,parent,null,parent,player,world,connection,config,5,7,service,4,9,20,null,true,false,false);assertTrue(l.ownsRetiredCleanupParent(retainedCamera,true,7,7));}
    @Test void typedDisabledCleanupRefusesReplacementControllerAuthorityAndInterveningLeg(){var l=lease();l.closed();var absent=new LegacyTravelPublicationIdentity.State(root,parent,null,null,player,world,connection,config,5,7,service,4,9,20,null,true,false,false);assertFalse(l.ownsRetiredCleanupParent(absent,false,7,7));assertFalse(l.ownsRetiredCleanupParent(absent,true,7,9));assertFalse(l.ownsRetiredCleanupParent(active(absent,new Object()),true,7,7));for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","journey","service","generation","epoch","serial","registration"})assertFalse(l.ownsRetiredCleanupParent(disabled(change(absent,field)),true,7,7),field);}
    @Test void stableClosedPredecessorHandoffMayChangeOnlyJourneyAndLeg(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);Object candidate=new Object();var admitted=LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,candidate,predecessor,predecessor,7,7,7);assertNotNull(admitted);assertTrue(admitted.current(active(next,candidate)));assertFalse(admitted.current(next));}
    @Test void noEffectIntermediateAdmissionAndRetirementCallbackRevokesHandoff(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);long[] version={7};Object[] active={null};Runnable callback=()->{Object intermediate=new Object();var nested=LegacyTravelPublicationIdentity.Lease.admit(predecessor,predecessor,intermediate,version[0],version[0]);assertNotNull(nested);active[0]=intermediate;version[0]++;nested.closed();active[0]=null;version[0]++;};callback.run();assertNull(active[0]);assertEquals(4,next.requestGeneration());assertEquals(9,next.epoch());assertEquals(20,next.publicationSerial());assertEquals(9,version[0]);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,new Object(),predecessor,predecessor,7,7,version[0]));}
    @Test void alreadyChangedAdmissionVersionCannotBeRecapturedAsPredecessorPermission(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,new Object(),predecessor,predecessor,7,9,9));}
    @Test void foreignOrNewerPredecessorOrSuccessorFieldsRefuseHandoff(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);for(String field:new String[]{"root","parent","input","camera","player","world","connection","config","revision","service","generation","epoch","serial","registration","disabled","scene"}){assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,new Object(),predecessor,change(predecessor,field),7,7,7),field);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,change(next,field),new Object(),predecessor,predecessor,7,7,7),field);}}
    @Test void originalPolicyLossCannotBeLaunderedThroughNewCandidateConfigCapture(){var predecessor=active(state(4,9),null);var changed=policy(journey(predecessor,8),5,true);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(changed,changed,new Object(),predecessor,predecessor,7,7,7));assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(journey(predecessor,8),journey(predecessor,8),new Object(),predecessor,policy(predecessor,3,false),7,7,7));}
    @Test void saturatedAdmissionVersionRejectsBeforeAnySuccessorPublication(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,new Object(),predecessor,predecessor,Long.MAX_VALUE,Long.MAX_VALUE,Long.MAX_VALUE));}
    @Test void occupiedActiveLegAndChangedPredecessorJourneyCannotSupplyHandoff(){var predecessor=active(state(4,9),null);var next=journey(predecessor,8);assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(active(next,new Object()),next,new Object(),predecessor,predecessor,7,7,7));assertNull(LegacyTravelPublicationIdentity.Lease.admitAfter(next,next,new Object(),predecessor,journey(predecessor,9),7,7,7));}
    @Test void expectedParentAdmissionCannotCaptureAnotherCurrentRootParent(){var vacant=active(state(4,9),null);assertNotNull(LegacyTravelPublicationIdentity.Lease.admitExpected(vacant,vacant,new Object(),parent,7,7));assertNull(LegacyTravelPublicationIdentity.Lease.admitExpected(vacant,vacant,new Object(),new Object(),7,7));assertNull(LegacyTravelPublicationIdentity.Lease.admitExpected(vacant,change(vacant,"input"),new Object(),parent,7,7));assertNull(LegacyTravelPublicationIdentity.Lease.admitExpected(vacant,change(vacant,"camera"),new Object(),parent,7,7));}
    @Test void interactionMintConsumesClosedLegExactlyOnceWithoutReopeningIt(){var l=lease();l.closed();var live=active(state(4,9),null);assertTrue(l.consumeRetiredInteraction(live,true,7,7));assertFalse(l.consumeRetiredInteraction(live,true,7,7));assertFalse(l.current(live));assertFalse(l.consumeRetiredInteraction(live,true,7,9));}
    @Test void failedOrPostCallbackAbaMintNeverConsumesFreshPermission(){var l=lease();l.closed();var live=active(state(4,9),null);assertFalse(l.consumeRetiredInteraction(live,true,7,9));assertFalse(l.consumeRetiredInteraction(policy(live,5,false),true,7,7));assertTrue(l.consumeRetiredInteraction(live,true,7,7));}
}










